steps.script:
var n = ScenarioRunner.event_log_count_containing("HOWLMAW")
var f = GameState.state.units["U_WOLF_PRIEST_A"].flags.get("sw11e_howlmaw_turn", "")
print("[sw11e howlmaw] events=", n, " stamp=", f, " shocked=", GameState.state.units["U_MEGANOBZ_A"].flags.get("battle_shocked", false))
return n >= 1 and f == "2:1"

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sw11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
